static struct timing_generator * dcn31_timing_generator_create ( struct dc_context * ctx , uint32_t instance ) { struct optc * tgn10 = kzalloc ( sizeof ( optc ) , GFP_KERNEL ) ; if ( ! tgn10 ) { return NULL ; } tgn10 -> base . inst = instance ; tgn10 -> base . ctx = ctx ; tgn10 -> tg_regs = & optc_regs [ instance ] ; tgn10 -> tg_shift = & optc_shift ; tgn10 -> tg_mask = & optc_mask ; return & tgn10 -> base ; } 